183 inline bool operator==( const D3D12_BOX& l, const D3D12_BOX& r ) noexcept
184 {
185     return l.left == r.left && l.top == r.top && l.front == r.front &&
186         l.right == r.right && l.bottom == r.bottom && l.back == r.back;
187 }
