218         D3D12_STENCIL_OP frontStencilFailOp,
219         D3D12_STENCIL_OP frontStencilDepthFailOp,
220         D3D12_STENCIL_OP frontStencilPassOp,
221         D3D12_COMPARISON_FUNC frontStencilFunc,
222         D3D12_STENCIL_OP backStencilFailOp,
