225         D3D12_COMPARISON_FUNC backStencilFunc ) noexcept
226     {
227         DepthEnable = depthEnable;
228         DepthWriteMask = depthWriteMask;
229         DepthFunc = depthFunc;
230         StencilEnable = stencilEnable;
231         StencilReadMask = stencilReadMask;
232         StencilWriteMask = stencilWriteMask;
233         FrontFace.StencilFailOp = frontStencilFailOp;
234         FrontFace.StencilDepthFailOp = frontStencilDepthFailOp;
235         FrontFace.StencilPassOp = frontStencilPassOp;
236         FrontFace.StencilFunc = frontStencilFunc;
237         BackFace.StencilFailOp = backStencilFailOp;
238         BackFace.StencilDepthFailOp = backStencilDepthFailOp;
239         BackFace.StencilPassOp = backStencilPassOp;
240         BackFace.StencilFunc = backStencilFunc;
241     }
