538 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 608)
539 struct CD3DX12_RASTERIZER_DESC1 : public D3D12_RASTERIZER_DESC1
540 {
541     CD3DX12_RASTERIZER_DESC1() = default;
542     explicit CD3DX12_RASTERIZER_DESC1(const D3D12_RASTERIZER_DESC1& o) noexcept :
543         D3D12_RASTERIZER_DESC1(o)
544 
545     {
546     }
547     explicit CD3DX12_RASTERIZER_DESC1(const D3D12_RASTERIZER_DESC& o) noexcept
548     {
549         FillMode = o.FillMode;
550         CullMode = o.CullMode;
