552         DepthBias = static_cast<FLOAT>(o.DepthBias);
553         DepthBiasClamp = o.DepthBiasClamp;
554         SlopeScaledDepthBias = o.SlopeScaledDepthBias;
555         DepthClipEnable = o.DepthClipEnable;
