751     {}
752     CD3DX12_HEAP_PROPERTIES(
753         D3D12_CPU_PAGE_PROPERTY cpuPageProperty,
754         D3D12_MEMORY_POOL memoryPoolPreference,
755         UINT creationNodeMask = 1,
756         UINT nodeMask = 1 ) noexcept
757     {
758         Type = D3D12_HEAP_TYPE_CUSTOM;
759         CPUPageProperty = cpuPageProperty;
760         MemoryPoolPreference = memoryPoolPreference;
761         CreationNodeMask = creationNodeMask;
762         VisibleNodeMask = nodeMask;
763     }
764     explicit CD3DX12_HEAP_PROPERTIES(
765         D3D12_HEAP_TYPE type,
766         UINT creationNodeMask = 1,
767         UINT nodeMask = 1 ) noexcept
768     {
769         Type = type;
770         CPUPageProperty = D3D12_CPU_PAGE_PROPERTY_UNKNOWN;
771         MemoryPoolPreference = D3D12_MEMORY_POOL_UNKNOWN;
772         CreationNodeMask = creationNodeMask;
773         VisibleNodeMask = nodeMask;
774     }
775     bool IsCPUAccessible() const noexcept
776     {
777         return Type == D3D12_HEAP_TYPE_UPLOAD || Type == D3D12_HEAP_TYPE_READBACK
778 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 609)
779             || Type == D3D12_HEAP_TYPE_GPU_UPLOAD
780 #endif
781             || (Type == D3D12_HEAP_TYPE_CUSTOM &&
782                 (CPUPageProperty == D3D12_CPU_PAGE_PROPERTY_WRITE_COMBINE || CPUPageProperty == D3D12_CPU_PAGE_PROPERTY_WRITE_BACK));
783     }
784 };
