788         l.MemoryPoolPreference == r.MemoryPoolPreference &&
789         l.CreationNodeMask == r.CreationNodeMask &&
790         l.VisibleNodeMask == r.VisibleNodeMask;
791 }
792 inline bool operator!=( const D3D12_HEAP_PROPERTIES& l, const D3D12_HEAP_PROPERTIES& r ) noexcept
793 { return !( l == r ); }
