881 struct CD3DX12_CLEAR_VALUE : public D3D12_CLEAR_VALUE
882 {
883     CD3DX12_CLEAR_VALUE() = default;
884     explicit CD3DX12_CLEAR_VALUE(const D3D12_CLEAR_VALUE &o) noexcept :
885         D3D12_CLEAR_VALUE(o)
886     {}
887     CD3DX12_CLEAR_VALUE(
888         DXGI_FORMAT format,
889         const FLOAT color[4] ) noexcept
890     {
891         Format = format;
892         memcpy( Color, color, sizeof( Color ) );
893     }
894     CD3DX12_CLEAR_VALUE(
895         DXGI_FORMAT format,
896         FLOAT depth,
897         UINT8 stencil ) noexcept
898     {
899         Format = format;
900         memset( &Color, 0, sizeof( Color ) );
901         /* Use memcpy to preserve NAN values */
902         memcpy( &DepthStencil.Depth, &depth, sizeof( depth ) );
903         DepthStencil.Stencil = stencil;
904     }
905 };
906 
907 //------------------------------------------------------------------------------------------------
908 inline bool operator==( const D3D12_CLEAR_VALUE &a, const D3D12_CLEAR_VALUE &b) noexcept
909 {
910     if (a.Format != b.Format) return false;
911     if (a.Format == DXGI_FORMAT_D24_UNORM_S8_UINT
912      || a.Format == DXGI_FORMAT_D16_UNORM
913      || a.Format == DXGI_FORMAT_D32_FLOAT
914      || a.Format == DXGI_FORMAT_D32_FLOAT_S8X24_UINT)
915     {
916         return (a.DepthStencil.Depth == b.DepthStencil.Depth) &&
917           (a.DepthStencil.Stencil == b.DepthStencil.Stencil);
918     } else {
919         return (a.Color[0] == b.Color[0]) &&
920                (a.Color[1] == b.Color[1]) &&
921                (a.Color[2] == b.Color[2]) &&
922                (a.Color[3] == b.Color[3]);
923     }
924 }
