1165 //------------------------------------------------------------------------------------------------
1166 constexpr UINT D3D12CalcSubresource( UINT MipSlice, UINT ArraySlice, UINT PlaneSlice, UINT MipLevels, UINT ArraySize ) noexcept
1167 {
1168     return MipSlice + ArraySlice * MipLevels + PlaneSlice * MipLevels * ArraySize;
1169 }
1170 
1171 //------------------------------------------------------------------------------------------------
1172 inline UINT8 D3D12GetFormatPlaneCount(
1173     _In_ ID3D12Device* pDevice,
1174     DXGI_FORMAT Format
1175     ) noexcept
1176 {
1177     D3D12_FEATURE_DATA_FORMAT_INFO formatInfo = { Format, 0 };
1178     if (FAILED(pDevice->CheckFeatureSupport(D3D12_FEATURE_FORMAT_INFO, &formatInfo, sizeof(formatInfo))))
1179     {
1180         return 0;
1181     }
1182     return formatInfo.PlaneCount;
1183 }
